const config = (function communityConfiguration(parameters) {
  if (parameters.operation !== 'startDeploymentScan') throw new Error('Configure the branded Create node for Start Deployment Scan.');
  return { enabled: false, ownershipConfirmed: parameters.ownershipConfirmed, termsAccepted: parameters.termsAccepted,
    termsVersion: '1.0', slackChannel: 'C_REPLACE_ME', maxPolls: 30, maxMinutes: 20,
    projects: { 'example-app': { origin: parameters.targetUrl, environment: 'production', eventNamespace: parameters.eventNamespace } } };
})($('Create deployment scan').params); return [{json:config}];

const event=$('Deployment webhook').first().json.body; const result=(function validateDeployment(event, config, now = Date.now()) {
  const wholeMatch = (value, pattern) => typeof value === 'string' && pattern.exec(value)?.[0] === value;
  if (config.enabled !== true || config.ownershipConfirmed !== true || config.termsAccepted !== true || config.termsVersion !== '1.0') {
    throw new Error('Scanning is disabled. Confirm target permission, accept VAS scanning terms and enable this workflow in configuration.');
  }
  if (!event || typeof event !== 'object' || Array.isArray(event)) throw new Error('Provide one normalized deployment event.');
  const project = Object.hasOwn(config.projects, event.project) ? config.projects[event.project] : undefined;
  if (!project || event.environment !== project.environment || event.status !== 'succeeded') {
    return { accepted: false }; // Unknown projects, previews and unsuccessful deploys cannot choose a URL.
  }
  if (!wholeMatch(event.eventId, /^[A-Za-z0-9][A-Za-z0-9:._/-]{0,79}$/) ||
      !wholeMatch(project.eventNamespace, /^[A-Za-z0-9][A-Za-z0-9._-]{0,31}$/)) {
    throw new Error('Provide a stable deployment ID and a configured event namespace. Keep the same ID on every retry.');
  }
  // No URL global is required in n8n's Code sandbox. Backend URL/DNS validation remains authoritative.
  if (!wholeMatch(project.origin, /^https:\/\/[a-z0-9](?:[a-z0-9.-]*[a-z0-9])?\.[a-z]{2,}\/?$/i)) {
    throw new Error('Configure a fixed HTTPS app origin without credentials, port, path, query or fragment.');
  }
  if (!wholeMatch(config.slackChannel, /^C[A-Z0-9]{8,}$/) || config.slackChannel.includes('REPLACE')) {
    throw new Error('Configure the approved Slack channel ID.');
  }
  if (!Number.isInteger(config.maxPolls) || config.maxPolls < 1 || config.maxPolls > 40 ||
      !Number.isInteger(config.maxMinutes) || config.maxMinutes < 1 || config.maxMinutes > 30) {
    throw new Error('Choose 1–40 status checks and a 1–30 minute time limit.');
  }
  return { accepted: true, key: `n8n:v1:${project.eventNamespace}:${event.eventId}`, targetUrl: project.origin.replace(/\/$/, ''),
    termsVersion: config.termsVersion, slackChannel: config.slackChannel,
    maxPolls: config.maxPolls, deadline: now + config.maxMinutes * 60_000 };
})(event,$input.first().json); return [{json:result.accepted ? {...result,deploymentId:event.eventId} : result}];

return [{json:(function acceptCreation(response, deployment) {
  const scanId = response?.body?.scanId;
  if (!Number.isInteger(response?.statusCode) || response.statusCode < 200 || response.statusCode >= 300 ||
      response.body?.contract !== 'deployment-scan-v1' ||
      typeof scanId !== 'string' || /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.exec(scanId)?.[0] !== scanId) {
    // Do not echo provider bodies, credentials, target evidence or unknown HTML error pages.
    throw new Error('VAS did not confirm this deployment scan. Check API access, allowance and endpoint availability; retry with the SAME deployment ID. Do not fall back to /scans.');
  }
  return { ...deployment, scanId: response.body.scanId, reused: response.body.deduplicated === true, polls: 0 };
})({statusCode:200,body:$input.first().json},$('Validate deployment').item.json)}];

return [{json:(function inspectCommunityStatus(result, state, now = Date.now()) {
  const base = { ...state, polls: state.polls + 1, pollAgain: false };
  if (!result || typeof result !== 'object' || typeof result.error === 'string') return { ...base, outcome: 'status-unavailable' };
  const terminal = ['completed', 'failed', 'cancelled', 'timeout', 'timed_out'];
  if (result.scanId !== state.scanId || ![...terminal, 'queued', 'running', 'processing'].includes(result.status) ||
      result.terminal !== terminal.includes(result.status)) return { ...base, outcome: 'invalid-status' };
  if (!result.terminal) return base.polls < state.maxPolls && now < state.deadline
    ? { ...base, pollAgain: true } : { ...base, outcome: 'wait-limit' };
  const number = value => Number.isSafeInteger(value) && value >= 0 ? value : null;
  return { ...base, outcome: result.status,
    counts: { total: number(result.counts?.total), critical: number(result.counts?.critical), high: number(result.counts?.high) },
    coverage: { pageCoverage: typeof result.coverage?.pageCoverage === 'string' ? result.coverage.pageCoverage : 'unknown',
      reportedChecks: number(result.coverage?.reportedChecks), incompleteChecks: number(result.coverage?.incompleteChecks),
      skippedChecks: number(result.coverage?.skippedChecks), boundedChecks: number(result.coverage?.boundedChecks) },
    reportLocked: result.reportAccess !== 'available' };
})($input.first().json,$('Wait before status').item.json)}];

return [{json: (function buildSummary(state) {
  const labels = { completed: 'Scan completed', failed: 'Scan failed', cancelled: 'Scan cancelled', timeout: 'Scan timed out',
    timed_out: 'Scan timed out', 'wait-limit': 'Stopped waiting; scan may still be running',
    'status-unavailable': 'Scan status could not be confirmed', 'access-blocked': 'VAS access needs attention',
    'report-unavailable': 'Report unavailable', 'invalid-status': 'Scan status could not be verified' };
  const lines = [`VAS: ${labels[state.outcome] ?? 'Scan result unknown'}.`, `App: ${state.targetUrl}`];
  if (['completed', 'failed', 'cancelled', 'timeout', 'timed_out'].includes(state.outcome)) {
    const number = n => n === null || n === undefined ? 'unknown' : String(n);
    lines.push(`Findings reported: ${number(state.counts?.total)}; critical: ${number(state.counts?.critical)}; high: ${number(state.counts?.high)}.`);
    const pageLabels = { unclassified: 'Application scope not classified', 'login-page': 'Login page only',
      'blocked-page': 'Application behind a blocked page was not assessed', 'placeholder-only': 'Placeholder content only',
      'parked-domain': 'Parked domain only', unreachable: 'Application unreachable',
      'reachability-unconfirmed': 'Application reachability not confirmed' };
    lines.push(`Coverage: ${pageLabels[state.coverage?.pageCoverage] ?? 'Application coverage unknown'}.`);
    lines.push(`Checks incomplete or unsuccessful: ${number(state.coverage?.incompleteChecks)} of ${number(state.coverage?.reportedChecks)} reported.`);
    if (state.coverage?.skippedChecks) lines.push(`Checks skipped or not applicable: ${state.coverage.skippedChecks}. These checks were not assessed.`);
    if (state.coverage?.boundedChecks) lines.push(`Checks limited to a bounded sample: ${state.coverage.boundedChecks}.`);
    if (state.reportLocked) lines.push('Detailed report access is not confirmed. Check your VAS account permissions.');
    lines.push('Completion and zero findings do not establish that the app is secure. Review report coverage and unresolved checks.');
  }
  if (state.outcome !== 'completed') lines.push('This is not a clean scan result. Inspect the existing scan; no replacement scan was started.');
  if (state.reused) lines.push('Reused the original scan for this deployment event.');
  // UUID was verified before interpolation; nothing from finding text or provider errors is included.
  lines.push(`Report: https://vibeappscanner.com/dashboard/scans/${state.scanId}`);
  return { channel: state.slackChannel, text: lines.join('\n'), mrkdwn: false, parse: 'none',
    link_names: false, unfurl_links: false, unfurl_media: false };
})($input.first().json)}];
